const VARIANT_CLASS_RULE: rt.StrRule = { pattern: new RegExp("^[a-z][a-z0-9_-]{0,63}$"), maxLen: 64, text: "none" };
export function decodeVariantClass(v: Value, path: string, _ctx: Ctx): VariantClass {
  return rt.string(v, path, VARIANT_CLASS_RULE) as VariantClass;
}
export function makeVariantClass(s: string): VariantClass {
  rt.checkString(s, "", VARIANT_CLASS_RULE);
  return s as VariantClass;
}
export function encodeVariantClass(x: VariantClass): Value {
  return x;
}

export interface VersionRange {
  min?: SemVer;
  max?: SemVer;
}
export function decodeVersionRangeFields(o: rt.Obj, ctx: Ctx): VersionRange {
  const path = o.path;
  const min_raw = o.opt("min");
  const min_ = min_raw === undefined ? undefined : decodeSemVer(min_raw, rt.child(path, "min"), ctx);
  const max_raw = o.opt("max");
  const max_ = max_raw === undefined ? undefined : decodeSemVer(max_raw, rt.child(path, "max"), ctx);
  o.finish();
  const out = {} as VersionRange;
  if (min_ !== undefined) out.min = min_;
  if (max_ !== undefined) out.max = max_;
  return out;
}
export function decodeVersionRange(v: Value, path: string, ctx: Ctx): VersionRange {
  return decodeVersionRangeFields(rt.Obj.of(v, path), ctx);
}
export function encodeVersionRangeFields(x: VersionRange): Map<string, Value> {
  const e = new Map<string, Value>();
  if (x.min !== undefined) e.set("min", encodeSemVer(x.min));
  if (x.max !== undefined) e.set("max", encodeSemVer(x.max));
  return e;
}
export function encodeVersionRange(x: VersionRange): Value {
  return encodeVersionRangeFields(x);
}

export interface SourceBinding {
  app_id: SourceAppId;
  variant_class: VariantClass;
  version_range?: VersionRange;
  capabilities: CapabilityId[];
}
export function decodeSourceBindingFields(o: rt.Obj, ctx: Ctx): SourceBinding {
  const path = o.path;
  const app_id_ = decodeSourceAppId(o.req("app_id"), rt.child(path, "app_id"), ctx);
  const variant_class_ = decodeVariantClass(o.req("variant_class"), rt.child(path, "variant_class"), ctx);
  const version_range_raw = o.opt("version_range");
  const version_range_ = version_range_raw === undefined ? undefined : decodeVersionRange(version_range_raw, rt.child(path, "version_range"), ctx);
  const capabilities_ = rt.list(o.req("capabilities"), rt.child(path, "capabilities"), 0, 64, (e, p) => decodeCapabilityId(e, p, ctx));
  o.finish();
  const out = {} as SourceBinding;
  out.app_id = app_id_;
  out.variant_class = variant_class_;
  if (version_range_ !== undefined) out.version_range = version_range_;
  out.capabilities = capabilities_;
  return out;
}
export function decodeSourceBinding(v: Value, path: string, ctx: Ctx): SourceBinding {
  return decodeSourceBindingFields(rt.Obj.of(v, path), ctx);
}
export function encodeSourceBindingFields(x: SourceBinding): Map<string, Value> {
  const e = new Map<string, Value>();
  e.set("app_id", encodeSourceAppId(x.app_id));
  e.set("variant_class", encodeVariantClass(x.variant_class));
  if (x.version_range !== undefined) e.set("version_range", encodeVersionRange(x.version_range));
  e.set("capabilities", x.capabilities.map((e) => encodeCapabilityId(e)));
  return e;
}
export function encodeSourceBinding(x: SourceBinding): Value {
  return encodeSourceBindingFields(x);
}

