/** What this specific runtime can observe, execute and persist under the current user's permissions. */
export interface EnvironmentCapabilityManifest {
  runtime_id: RuntimeId;
  mode: ExecutionMode;
  runtime_version: SemVer;
  compiler_version: CompilerVersion;
  generated_at: Instant;
  principal_ref: PrincipalRef;
  permissions: PermissionGrant[];
  observation: CapabilityEntry[];
  execution: CapabilityEntry[];
  persistence: PersistenceLevel;
  credential_isolation: CredentialIsolation;
  egress: EgressPolicy;
  limits: Limits;
  attestation?: Attestation;
  app_id?: SourceAppId;
  variant_id?: SourceVariantId;
}
export function decodeEnvironmentCapabilityManifestFields(o: rt.Obj, ctx: Ctx): EnvironmentCapabilityManifest {
  const path = o.path;
  const runtime_id_ = decodeRuntimeId(o.req("runtime_id"), rt.child(path, "runtime_id"), ctx);
  const mode_ = decodeExecutionMode(o.req("mode"), rt.child(path, "mode"), ctx);
  const runtime_version_ = decodeSemVer(o.req("runtime_version"), rt.child(path, "runtime_version"), ctx);
  const compiler_version_ = decodeCompilerVersion(o.req("compiler_version"), rt.child(path, "compiler_version"), ctx);
  const generated_at_ = decodeInstant(o.req("generated_at"), rt.child(path, "generated_at"), ctx);
  const principal_ref_ = decodePrincipalRef(o.req("principal_ref"), rt.child(path, "principal_ref"), ctx);
  const permissions_ = rt.list(o.req("permissions"), rt.child(path, "permissions"), 0, 256, (e, p) => decodePermissionGrant(e, p, ctx));
  const observation_ = rt.list(o.req("observation"), rt.child(path, "observation"), 0, 256, (e, p) => decodeCapabilityEntry(e, p, ctx));
  const execution_ = rt.list(o.req("execution"), rt.child(path, "execution"), 0, 256, (e, p) => decodeCapabilityEntry(e, p, ctx));
  const persistence_ = decodePersistenceLevel(o.req("persistence"), rt.child(path, "persistence"), ctx);
  const credential_isolation_ = decodeCredentialIsolation(o.req("credential_isolation"), rt.child(path, "credential_isolation"), ctx);
  const egress_ = decodeEgressPolicy(o.req("egress"), rt.child(path, "egress"), ctx);
  const limits_ = decodeLimits(o.req("limits"), rt.child(path, "limits"), ctx);
  const attestation_raw = o.opt("attestation");
  const attestation_ = attestation_raw === undefined ? undefined : decodeAttestation(attestation_raw, rt.child(path, "attestation"), ctx);
  const app_id_raw = o.since("app_id", [1, 1, 0], false, ctx);
  const app_id_ = app_id_raw === undefined ? undefined : decodeSourceAppId(app_id_raw, rt.child(path, "app_id"), ctx);
  const variant_id_raw = o.since("variant_id", [1, 1, 0], false, ctx);
  const variant_id_ = variant_id_raw === undefined ? undefined : decodeSourceVariantId(variant_id_raw, rt.child(path, "variant_id"), ctx);
  o.finish();
  const out = {} as EnvironmentCapabilityManifest;
  out.runtime_id = runtime_id_;
  out.mode = mode_;
  out.runtime_version = runtime_version_;
  out.compiler_version = compiler_version_;
  out.generated_at = generated_at_;
  out.principal_ref = principal_ref_;
  out.permissions = permissions_;
  out.observation = observation_;
  out.execution = execution_;
  out.persistence = persistence_;
  out.credential_isolation = credential_isolation_;
  out.egress = egress_;
  out.limits = limits_;
  if (attestation_ !== undefined) out.attestation = attestation_;
  if (app_id_ !== undefined) out.app_id = app_id_;
  if (variant_id_ !== undefined) out.variant_id = variant_id_;
  return out;
}
export function decodeEnvironmentCapabilityManifest(v: Value, path: string, ctx: Ctx): EnvironmentCapabilityManifest {
  return decodeEnvironmentCapabilityManifestFields(rt.Obj.of(v, path), ctx);
}
export function encodeEnvironmentCapabilityManifestFields(x: EnvironmentCapabilityManifest): Map<string, Value> {
  const e = new Map<string, Value>();
  e.set("runtime_id", encodeRuntimeId(x.runtime_id));
  e.set("mode", encodeExecutionMode(x.mode));
  e.set("runtime_version", encodeSemVer(x.runtime_version));
  e.set("compiler_version", encodeCompilerVersion(x.compiler_version));
  e.set("generated_at", encodeInstant(x.generated_at));
  e.set("principal_ref", encodePrincipalRef(x.principal_ref));
  e.set("permissions", x.permissions.map((e) => encodePermissionGrant(e)));
  e.set("observation", x.observation.map((e) => encodeCapabilityEntry(e)));
  e.set("execution", x.execution.map((e) => encodeCapabilityEntry(e)));
  e.set("persistence", encodePersistenceLevel(x.persistence));
  e.set("credential_isolation", encodeCredentialIsolation(x.credential_isolation));
  e.set("egress", encodeEgressPolicy(x.egress));
  e.set("limits", encodeLimits(x.limits));
  if (x.attestation !== undefined) e.set("attestation", encodeAttestation(x.attestation));
  if (x.app_id !== undefined) e.set("app_id", encodeSourceAppId(x.app_id));
  if (x.variant_id !== undefined) e.set("variant_id", encodeSourceVariantId(x.variant_id));
  return e;
}
export function encodeEnvironmentCapabilityManifest(x: EnvironmentCapabilityManifest): Value {
  return encodeEnvironmentCapabilityManifestFields(x);
}

