export type ClaimValue =
  | ({ kind: "text" } & ClaimText)
  | ({ kind: "int" } & ClaimInt)
  | ({ kind: "bool" } & ClaimBool)
  | ({ kind: "effect" } & ClaimEffect)
  | ({ kind: "value_type" } & ClaimValueType)
  | ({ kind: "decimal" } & ClaimDecimal)
  | ({ kind: "date" } & ClaimDate)
  | ({ kind: "instant" } & ClaimInstant)
  | ({ kind: "money" } & ClaimMoney);
export function decodeClaimValue(v: Value, path: string, ctx: Ctx): ClaimValue {
  const o = rt.Obj.of(v, path);
  const tag = rt.enumStr(o.req("kind"), rt.child(path, "kind"));
  switch (tag) {
    case "text":
      return { kind: "text", ...decodeClaimTextFields(o, ctx) };
    case "int":
      return { kind: "int", ...decodeClaimIntFields(o, ctx) };
    case "bool":
      return { kind: "bool", ...decodeClaimBoolFields(o, ctx) };
    case "effect":
      return { kind: "effect", ...decodeClaimEffectFields(o, ctx) };
    case "value_type":
      return { kind: "value_type", ...decodeClaimValueTypeFields(o, ctx) };
    case "decimal":
      return { kind: "decimal", ...decodeClaimDecimalFields(o, ctx) };
    case "date":
      return { kind: "date", ...decodeClaimDateFields(o, ctx) };
    case "instant":
      return { kind: "instant", ...decodeClaimInstantFields(o, ctx) };
    case "money":
      return { kind: "money", ...decodeClaimMoneyFields(o, ctx) };
    default:
      throw new rt.IrError(rt.child(path, "kind"), "ir.unknown_variant");
  }
}
export function encodeClaimValue(x: ClaimValue): Value {
  switch (x.kind) {
    case "text": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimTextFields(rest as ClaimText);
      e.set("kind", "text");
      return e;
    }
    case "int": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimIntFields(rest as ClaimInt);
      e.set("kind", "int");
      return e;
    }
    case "bool": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimBoolFields(rest as ClaimBool);
      e.set("kind", "bool");
      return e;
    }
    case "effect": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimEffectFields(rest as ClaimEffect);
      e.set("kind", "effect");
      return e;
    }
    case "value_type": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimValueTypeFields(rest as ClaimValueType);
      e.set("kind", "value_type");
      return e;
    }
    case "decimal": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimDecimalFields(rest as ClaimDecimal);
      e.set("kind", "decimal");
      return e;
    }
    case "date": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimDateFields(rest as ClaimDate);
      e.set("kind", "date");
      return e;
    }
    case "instant": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimInstantFields(rest as ClaimInstant);
      e.set("kind", "instant");
      return e;
    }
    case "money": {
      const { kind: _tag, ...rest } = x;
      const e = encodeClaimMoneyFields(rest as ClaimMoney);
      e.set("kind", "money");
      return e;
    }
  }
}

/** An explicit, evidence-linked statement; support and contradiction are kept apart. */
export interface Claim {
  id: Ident;
  subject: Ident;
  predicate: ClaimPredicate;
  value: ClaimValue;
  supports: Ident[];
  contradicts: Ident[];
  certainty: Certainty;
}
export function decodeClaimFields(o: rt.Obj, ctx: Ctx): Claim {
  const path = o.path;
  const id_ = decodeIdent(o.req("id"), rt.child(path, "id"), ctx);
  const subject_ = decodeIdent(o.req("subject"), rt.child(path, "subject"), ctx);
  const predicate_ = decodeClaimPredicate(o.req("predicate"), rt.child(path, "predicate"), ctx);
  const value_ = decodeClaimValue(o.req("value"), rt.child(path, "value"), ctx);
  const supports_ = rt.list(o.req("supports"), rt.child(path, "supports"), 0, 64, (e, p) => decodeIdent(e, p, ctx));
  const contradicts_ = rt.list(o.req("contradicts"), rt.child(path, "contradicts"), 0, 64, (e, p) => decodeIdent(e, p, ctx));
  const certainty_ = decodeCertainty(o.req("certainty"), rt.child(path, "certainty"), ctx);
  o.finish();
  const out = {} as Claim;
  out.id = id_;
  out.subject = subject_;
  out.predicate = predicate_;
  out.value = value_;
  out.supports = supports_;
  out.contradicts = contradicts_;
  out.certainty = certainty_;
  return out;
}
export function decodeClaim(v: Value, path: string, ctx: Ctx): Claim {
  return decodeClaimFields(rt.Obj.of(v, path), ctx);
}
export function encodeClaimFields(x: Claim): Map<string, Value> {
  const e = new Map<string, Value>();
  e.set("id", encodeIdent(x.id));
  e.set("subject", encodeIdent(x.subject));
  e.set("predicate", encodeClaimPredicate(x.predicate));
  e.set("value", encodeClaimValue(x.value));
  e.set("supports", x.supports.map((e) => encodeIdent(e)));
  e.set("contradicts", x.contradicts.map((e) => encodeIdent(e)));
  e.set("certainty", encodeCertainty(x.certainty));
  return e;
}
export function encodeClaim(x: Claim): Value {
  return encodeClaimFields(x);
}

export interface SemanticIR {
  source_app_id: SourceAppId;
  source_variant_id: SourceVariantId;
  observations: ObservationEpoch[];
  compiler_version: CompilerVersion;
  primitive_set: Digest;
  entities: Entity[];
  relationships: Relationship[];
  actions: ActionDef[];
  state_machines: StateMachine[];
  evidence: EvidenceDef[];
  claims: Claim[];
}
export function decodeSemanticIRFields(o: rt.Obj, ctx: Ctx): SemanticIR {
  const path = o.path;
  const source_app_id_ = decodeSourceAppId(o.req("source_app_id"), rt.child(path, "source_app_id"), ctx);
  const source_variant_id_ = decodeSourceVariantId(o.req("source_variant_id"), rt.child(path, "source_variant_id"), ctx);
  const observations_ = rt.list(o.req("observations"), rt.child(path, "observations"), 0, 256, (e, p) => decodeObservationEpoch(e, p, ctx));
  const compiler_version_ = decodeCompilerVersion(o.req("compiler_version"), rt.child(path, "compiler_version"), ctx);
  const primitive_set_ = decodeDigest(o.req("primitive_set"), rt.child(path, "primitive_set"), ctx);
  const entities_ = rt.list(o.req("entities"), rt.child(path, "entities"), 0, 4096, (e, p) => decodeEntity(e, p, ctx));
  const relationships_ = rt.list(o.req("relationships"), rt.child(path, "relationships"), 0, 16384, (e, p) => decodeRelationship(e, p, ctx));
  const actions_ = rt.list(o.req("actions"), rt.child(path, "actions"), 0, 4096, (e, p) => decodeActionDef(e, p, ctx));
  const state_machines_ = rt.list(o.req("state_machines"), rt.child(path, "state_machines"), 0, 1024, (e, p) => decodeStateMachine(e, p, ctx));
  const evidence_ = rt.list(o.req("evidence"), rt.child(path, "evidence"), 0, 65536, (e, p) => decodeEvidenceDef(e, p, ctx));
  const claims_ = rt.list(o.req("claims"), rt.child(path, "claims"), 0, 65536, (e, p) => decodeClaim(e, p, ctx));
  o.finish();
  const out = {} as SemanticIR;
  out.source_app_id = source_app_id_;
  out.source_variant_id = source_variant_id_;
  out.observations = observations_;
  out.compiler_version = compiler_version_;
  out.primitive_set = primitive_set_;
  out.entities = entities_;
  out.relationships = relationships_;
  out.actions = actions_;
  out.state_machines = state_machines_;
  out.evidence = evidence_;
  out.claims = claims_;
  return out;
}
export function decodeSemanticIR(v: Value, path: string, ctx: Ctx): SemanticIR {
  return decodeSemanticIRFields(rt.Obj.of(v, path), ctx);
}
export function encodeSemanticIRFields(x: SemanticIR): Map<string, Value> {
  const e = new Map<string, Value>();
  e.set("source_app_id", encodeSourceAppId(x.source_app_id));
  e.set("source_variant_id", encodeSourceVariantId(x.source_variant_id));
  e.set("observations", x.observations.map((e) => encodeObservationEpoch(e)));
  e.set("compiler_version", encodeCompilerVersion(x.compiler_version));
  e.set("primitive_set", encodeDigest(x.primitive_set));
  e.set("entities", x.entities.map((e) => encodeEntity(e)));
  e.set("relationships", x.relationships.map((e) => encodeRelationship(e)));
  e.set("actions", x.actions.map((e) => encodeActionDef(e)));
  e.set("state_machines", x.state_machines.map((e) => encodeStateMachine(e)));
  e.set("evidence", x.evidence.map((e) => encodeEvidenceDef(e)));
  e.set("claims", x.claims.map((e) => encodeClaim(e)));
  return e;
}
export function encodeSemanticIR(x: SemanticIR): Value {
  return encodeSemanticIRFields(x);
}

