export interface ParamDef {
  type: ValueType;
  required: boolean;
  choices?: Label[];
  unit?: Unit;
  description?: Label;
}
export function decodeParamDefFields(o: rt.Obj, ctx: Ctx): ParamDef {
  const path = o.path;
  const type_ = decodeValueType(o.req("type"), rt.child(path, "type"), ctx);
  const required_ = rt.boolean(o.req("required"), rt.child(path, "required"));
  const choices_raw = o.opt("choices");
  const choices_ = choices_raw === undefined ? undefined : rt.list(choices_raw, rt.child(path, "choices"), 0, 256, (e, p) => decodeLabel(e, p, ctx));
  const unit_raw = o.opt("unit");
  const unit_ = unit_raw === undefined ? undefined : decodeUnit(unit_raw, rt.child(path, "unit"), ctx);
  const description_raw = o.opt("description");
  const description_ = description_raw === undefined ? undefined : decodeLabel(description_raw, rt.child(path, "description"), ctx);
  o.finish();
  const out = {} as ParamDef;
  out.type = type_;
  out.required = required_;
  if (choices_ !== undefined) out.choices = choices_;
  if (unit_ !== undefined) out.unit = unit_;
  if (description_ !== undefined) out.description = description_;
  return out;
}
export function decodeParamDef(v: Value, path: string, ctx: Ctx): ParamDef {
  return decodeParamDefFields(rt.Obj.of(v, path), ctx);
}
export function encodeParamDefFields(x: ParamDef): Map<string, Value> {
  const e = new Map<string, Value>();
  e.set("type", encodeValueType(x.type));
  e.set("required", x.required);
  if (x.choices !== undefined) e.set("choices", x.choices.map((e) => encodeLabel(e)));
  if (x.unit !== undefined) e.set("unit", encodeUnit(x.unit));
  if (x.description !== undefined) e.set("description", encodeLabel(x.description));
  return e;
}
export function encodeParamDef(x: ParamDef): Value {
  return encodeParamDefFields(x);
}

